/**
 * Parity contract with build/mg/fold.py.
 *
 * These cases are generated by the Python side, so a failure here means the two
 * tokenisers have diverged — which would make indexed tokens unreachable at query time
 * without any visible error.
 */
import { describe, expect, it } from 'vitest'
import { fold, foldKey, foldTokens } from './fold'
import fixture from '../../../fixtures/folding_cases.json'

describe('fold parity with the Python implementation', () => {
  it('matches every pinned case', () => {
    const mismatches = fixture.cases
      .filter((c) => fold(c.in) !== c.out)
      .map((c) => `${JSON.stringify(c.in)}: expected ${JSON.stringify(c.out)}, got ${JSON.stringify(fold(c.in))}`)
    expect(mismatches).toEqual([])
  })

  it('folds corpus and user spellings to the same value', () => {
    const mismatches = fixture.equivalences
      .filter((e) => fold(e.corpus) !== fold(e.user) || fold(e.corpus) !== e.folded)
      .map((e) => `${e.corpus} -> ${fold(e.corpus)} vs ${e.user} -> ${fold(e.user)}`)
    expect(mismatches).toEqual([])
  })
})

describe('fold', () => {
  it('is idempotent', () => {
    for (const c of fixture.cases) {
      const once = fold(c.in)
      expect(fold(once), `not idempotent for ${JSON.stringify(c.in)}`).toBe(once)
    }
  })

  it('returns empty for punctuation-only input', () => {
    for (const s of ['', '   ', '|| ||', '---', '\n\n', ':', '.']) {
      expect(fold(s)).toBe('')
      expect(foldTokens(s)).toEqual([])
    }
  })

  it('never emits empty tokens', () => {
    for (const c of fixture.cases) {
      expect(foldTokens(c.in).every((t) => t.length > 0)).toBe(true)
    }
  })

  it('keeps digits', () => {
    expect(fold('Vol 17')).toBe('vol 17')
    expect(foldTokens('01 - Thodaya Mangalam')).toEqual(['01', 'todaya', 'mangalam'])
  })

  it('does not empty a bare h', () => {
    expect(fold('h')).toBe('h')
    expect(fold('ah')).toBe('a')
  })
})

describe('foldKey', () => {
  it('removes spaces', () => {
    expect(foldKey('Sri Sri Anna')).toBe('srisriana')
    expect(foldKey('H H Sri Sri Muralidhara Swamiji')).not.toContain(' ')
  })
})
